class Entitlement(KaitenModel):
    """A catalog entry: something a license can grant, and how its usage is measured."""

    aggregation_method: AggregationMethod | str | None = Field(
        default=None, alias="aggregationMethod"
    )
    """Method used to fold each reported usage value into the stored total (NUMBER only).
    Defaults to SUM.
    """

    created_at: datetime = Field(alias="createdAt")
    """Timestamp when this entitlement was created"""

    description: str | None
    """Description of the entitlement"""

    display_order: int | None = Field(default=None, alias="displayOrder")
    """Sort order of this entitlement in customer-facing components (ascending). Defaults to 0."""

    entitlement_groups: list[EntitlementGroupSummary] | None = Field(
        default=None, alias="entitlementGroups"
    )
    """Groups associated with this entitlement"""

    group_slugs: list[str] | None = Field(default=None, alias="groupSlugs")
    """Groups associated with this entitlement, identified by slug"""

    icon: str | None = None
    """Optional icon, stored as a provider-namespaced token (provider:name). Decoupled from any
    specific icon library.
    """

    id: str
    """Unique identifier for the entitlement"""

    name: str
    """Name of the entitlement"""

    reset_anchor: ResetAnchor | str | None = Field(default=None, alias="resetAnchor")
    """Phase of the periodic usage window: CALENDAR (UTC calendar-aligned), LICENSE_START
    (phased off the instance's license start date) or BILLING_PERIOD (phased off the
    instance's live subscription's billing anchor, LICENSE_START without one; with
    resetPeriod MONTH or YEAR only). Required exactly when resetPeriod is set; defaults to
    CALENDAR when omitted. Immutable once set.
    """

    reset_period: ResetPeriod | str | None = Field(default=None, alias="resetPeriod")
    """Cadence at which usage automatically resets for this NUMBER entitlement. NULL means a
    lifetime counter (default). Immutable once set -- a full-replace PUT must echo back the
    stored value.
    """

    sale_unit_factor: float | None = Field(default=None, alias="saleUnitFactor")
    """Number of base units one sale unit represents (1 sale unit = N base units)."""

    sale_unit_plural: str | None = Field(default=None, alias="saleUnitPlural")
    """Plural label of the unit this entitlement is sold in, when it differs from the base unit."""

    sale_unit_singular: str | None = Field(default=None, alias="saleUnitSingular")
    """Singular label of the unit this entitlement is sold in, when it differs from the base
    unit. Requires the base unit labels and the full sale unit trio (saleUnitSingular,
    saleUnitPlural, saleUnitFactor).
    """

    slug: str | None = None
    """Optional URL-friendly identifier, unique per organization. Auto-generated if not provided."""

    type: EntitlementType | str | None = None
    """Type of the entitlement"""

    unit_plural: str | None = Field(default=None, alias="unitPlural")
    """Plural label of the base unit this entitlement is measured in (NUMBER type only). Must
    be provided together with unitSingular.
    """

    unit_singular: str | None = Field(default=None, alias="unitSingular")
    """Singular label of the base unit this entitlement is measured in (NUMBER type only). Must
    be provided together with unitPlural.
    """

    updated_at: datetime = Field(alias="updatedAt")
    """Timestamp when this entitlement was last updated"""

    user_facing: bool | None = Field(default=None, alias="userFacing")
    """Whether this entitlement is displayed in customer-facing components (e.g. plan and
    pricing pages). Defaults to false.
    """

    warning_threshold_percent: int | None = Field(default=None, alias="warningThresholdPercent")
    """Percentage of the cap at which an early-warning event fires before the cap is reached. 0
    disables the warning (default).
    """


